import re,os

'''list --> set[sets]'''
def to_set(dat:list[dict]) -> set[tuple]:
    res = []
    for record in dat:
        for val in record.values():
            res.append(tuple(sorted(val)))
    return set(res)
    
def to_str(s:set[tuple]) -> str:
    return ' '.join([str(j) for i in s for j in i])
        




