_initial = to_set(initial)
_after_opt = to_set(after_opt)
_after_soft = to_set(after_soft)


after_soft_ok = []
after_soft_new = []
for val in after_soft:
    bond = tuple(sorted(val['bond']))
    ring = tuple(sorted(val['ring']))
    # if bond not in _initial or ring not in _initial:
    if ring not in _initial:
        after_soft_new.append(val)
    else:
        after_soft_ok.append(val)
        
after_opt = after_soft_ok
_after_opt = to_set(after_soft_ok)
_after_soft_new = to_set(after_soft_new)
other = [j for i in _after_soft_new for j in i]

green = []
red = []
N=0
ri = set([j for i in after_opt for j in i['ring']])
bi = set([j for i in after_opt for j in i['bond']])
for val in initial:
    bond = tuple(sorted(val['bond']))
    ring = tuple(sorted(val['ring']))
    if ring in _after_opt:
        red+=list(ring)
    else:
        if bi.intersection(set(ring))==set():
            green+=list(ring)
        else:
            red+=list(ring)
    if not ri.issuperset(set(bond)):
        # assert bond[0] not in ri
        # assert bond[1] not in ri
        if bond in _after_opt:
            red+=list(bond)
        else:
            if ri.intersection(set(bond)) == set():
                green+=list(bond)
            else:
                pass
    else:
        N+=1

print(f'GREEN: {" ".join([str(i) for i in green])}\n\n')
print(f'RED: {" ".join([str(i) for i in red])}\n\n')
print(f'BLUE: {" ".join([str(i) for i in other])}\n\n')
print(N)


